uint16_t demo_buttons(int stage, unsigned frame)
{
    const uint8_t *p;
    size_t i;
    unsigned at = 0;

    if (stage < 1 || stage > 5) {
        return 0;
    }
    p = k_rec[stage - 1];
    for (i = 0; i + 1 < k_len[stage - 1]; i += 2) {
        at += p[i];
        if (frame < at) {
            return p[i + 1];
        }
    }
    return 0;
}
